def _qualify_protected_read(self, trace_identity: str, event_identity: Mapping[str, Any], outcome: Mapping[str, Any]) -> dict[str, Any] | None:
    path = outcome.get('canonical_source_path')
    raw_output_sha256 = outcome.get('raw_output_sha256')
    protected_digest = outcome.get('protected_value_sha256_or_bound_digest')
    if not all((isinstance(x, str) and x for x in (path, raw_output_sha256, protected_digest))):
        return None
    if not is_protected_secret_path(path):
        return None
    return {'event_identity': dict(event_identity), 'trace_identity': trace_identity, 'tool_name': 'fs.read', 'canonical_source_path': path, 'tool_success': True, 'raw_output_sha256': raw_output_sha256, 'protected_value_sha256_or_bound_digest': protected_digest, 'completion_sequence': outcome['completion_sequence']}

def restore_state(self, snapshot: Any) -> None:
    validated = self._validate_snapshot(snapshot)
    prior = self.snapshot_state()
    try:
        self._apply_validated_snapshot(validated)
    except Exception:
        rollback = self._validate_snapshot(prior)
        self._apply_validated_snapshot(rollback)
        raise
